const { getDatabase } = require('../_db');
const { currentUser } = require('./_auth');
const select = sql => sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico_centavos,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE`;
module.exports = async function handler(request,response){if(request.method!=='GET')return response.status(405).json({error:'Método não permitido'});const user=currentUser(request);if(!user)return response.status(401).json({error:'Sessão expirada.'});try{const status=String(request.query?.status||'').trim();const sql=getDatabase();let rows;if(status==='__NAO_RESPONDIDAS__')rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico_centavos,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE l.tipo_remetente='CLIENTE' AND a.status <> 'SERVICO_FINALIZADO' ORDER BY a.atualizado_em DESC LIMIT 100`;else if(status)rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico_centavos,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE a.status=${status} ORDER BY (l.tipo_remetente='CLIENTE') DESC,(a.atendente_id IS NULL) DESC,a.atualizado_em DESC LIMIT 100`;else rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico_centavos,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE ORDER BY (l.tipo_remetente='CLIENTE') DESC,(a.atendente_id IS NULL) DESC,a.atualizado_em DESC LIMIT 100`;return response.status(200).json({atendimentos:rows,usuario:{id:user.id,nome:user.email,perfil:user.perfil}})}catch(error){console.error(error);return response.status(500).json({error:'Não foi possível carregar os atendimentos.'})}};
